INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('bd0c2537-5fe6-40f8-9cbb-da19cbb5d86f', 'Vigencia', 'Todas las fechas en el contrato se determinan a partir de la entrega del local. Modificar cuando se tenga el acta de entrega', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('bd0c2537-5fe6-40f8-9cbb-da19cbb5d86f', 'Late Fees', '6', '4', 'INTERESES POR MORA', E'- If the tenant is late in paying rent, maintenance, administration, or advertising fees, they must also pay late interest.\n- The late interest rate is the TIIE (Interbank Equilibrium Interest Rate) plus 2% per day of delay.\n- Interest is calculated annually over 360 days and based on the exact number of days late.\n- If the tenant fails to pay any amount due for rent, maintenance, advertising, or hydraulic network, they must pay a penalty.\n- The penalty is 100% of the amount owed, in addition to the original amount due.', E'Si LA ARRENDATARIA incurre en mora en el pago de las mismas, se obliga a pagar, además de LA RENTA, MANTENIMIENTO, ADMINISTRACIÓN Y PUBLICIDAD que le corresponda conforme el presente Contrato, intereses moratorios a razón de una tasa máxima anual de TIIE (Tasa de Interés Interbancaria de Equilibrio) mas 2 (dos) puntos porcentuales por cada día de retraso, es decir los intereses moratorios se calcularán considerando la tasa anual sobre (360 días) y por el número exacto de días transcurridos en mora. \n\nVIGÉSIMA PRIMERA.- PENA CONVENCIONAL: En caso de que el incumplimiento corresponda a la falta de pago de cualquier cantidad a cargo de LA ARRENDATARIA por concepto de RENTA, MANTENIMIENTO, PUBLICIDAD Y RED HIDRÁULICA, LA ARRENDATARIA deberá pagar una pena convencional equivalente al 100% (CIEN POR CIENTO) del importe adeudado, lo anterior sin contar la obligación de pago del importe adeudado.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('bd0c2537-5fe6-40f8-9cbb-da19cbb5d86f', 'Incremento de Renta', '1', NULL, 'AJUSTE DE RENTA', E'- El incremento será anual, cada enero.\n- Se basará en el aumento del Índice Nacional de Precios al Consumidor (INPC) del año anterior.\n- Si el INPC no está disponible, se usará el índice de los últimos 12 meses conocidos.\n- La primera actualización será en enero de 2027, usando el INPC de los últimos 19 meses conocidos.', 'Será incrementada ANUALMENTE, durante el mes de ENERO de cada año, en el mismo porcentaje en que se incremente el Índice Nacional de Precios al Consumidor (INPC) que publica el Instituto Nacional de Estadística y Geografía, o el índice que expresamente substituya a este último, correspondiente a los DOCE meses inmediatos anteriores a aquel en que proceda dicho incremento, en el entendido de que de no conocerse el índice de que se trata para el período señalado, el índice que en su caso se aplicará, será el que corresponda al de los últimos DOCE meses publicados o conocidos. Su primera indexación será en el mes de ENERO DE 2027, con base al INPC de los últimos 19 (DIECINUEVE) meses publicados o conocidos.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('bd0c2537-5fe6-40f8-9cbb-da19cbb5d86f', 'Common Area Maintenance Charges', '2', NULL, 'MANTENIMIENTO, ADMINISTRACIÓN Y PUBLICIDAD', E'- The tenant will pay monthly, starting from the delivery of the premises, 8% of the guaranteed monthly rent for maintenance and administration costs, plus VAT.\n- The tenant will also pay 2% for advertising costs, plus VAT.\n- These payments are in addition to the rent.\n- The tenant agrees to contribute to the shopping center''s maintenance, administration, and advertising costs as defined in the agreement, plus VAT.\n- The VAT will be charged separately and will increase proportionally with any rent adjustments.', E'LA ARRENDATARIA contribuirá mensualmente a partir del ACTA DE ENTREGA del LOCAL, con el 8% (OCHO POR CIENTO) de la cantidad establecida como RENTA MENSUAL GARANTIZADA, por concepto de gastos de mantenimiento y administración más el Impuesto al Valor Agregado y por gastos de publicidad con el 2% (DOS POR CIENTO), más el Impuesto al Valor Agregado.\n\nLAS PARTES convienen que, independiente de las obligaciones de pago de LA RENTA a cargo de LA ARRENDATARIA, ésta se obliga a contribuir en los gastos de MANTENIMIENTO, ADMINISTRACIÓN Y PUBLICIDAD, del Centro Comercial en los términos y condiciones que para tal efecto se precisan en el capítulo de definiciones, más el Impuesto al Valor Agregado, el cual será trasladado en forma expresa y por separado en términos de ley, importe que será incrementado en la misma forma y proporción que el AJUSTE DE RENTA.');
