":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":57638,"grid_name":"Punto Sur","grid_full_address":"235/312 Avenida Paseo Punto Sur, LN202, Los Gavilanes, Tlajomulco De Zuñiga, Jalisco 45645","map_addr_1":"235/312 Avenida Paseo Punto Sur","map_addr_2":"LN202","map_city_state_zip":"Los Gavilanes, Tlajomulco De Zuñiga, Jalisco 45645","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2025-09-25 15:05:20","active_lease_count_over_time":50853,"location_count_over_time":57638,"remaining_rent_liability_over_time":50853,"base_rent_current_month":"246356.6000","cam_current_month":"24635.6600","base_rent_next_month":"246356.6000","cam_next_month":"24635.6600","base_rent_per_square_meter":"1680.00","cam_per_square_meter":"168.00","base_rent_per_year":"2956279.2000","cam_per_year":"295627.9200"}'::jsonb);
