INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('f9873222-3c05-49c4-8a74-a3eb12367c8f', 'Fecha de Apertura', '31 de diciembre de 2025', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f9873222-3c05-49c4-8a74-a3eb12367c8f', 'Late Fees', '4', '2.III', 'INTERESES MORATORIOS', E'- If the tenant does not pay the rent, VAT, or any other amount on time as required by the contract, they must pay a late interest to the landlord.\n- The late interest is calculated from the start of the delay until the overdue amount is fully paid.\n- The interest rate is 3% per month.\n- The interest is calculated monthly, even if the delay is only for one day.', 'Para el caso de que el ARRENDATARIO no cubra puntualmente la renta y su respectivo Impuesto al Valor Agregado (IVA), o cualquier otra cantidad que deba pagar de acuerdo a lo establecido en el CONTRATO, éste conviene y se obliga a pagar a la ARRENDADORA, un interés moratorio que habrá de ser calculado a partir de la fecha del inicio de la mora y hasta la fecha en que efectivamente se haga pago del adeudo en mora, a la tasa de interés del 3% (tres por ciento) mensual. El cómputo de este interés moratorio se hará por periodos mensuales no obstante que la morosidad corresponda a 1 (Un) sólo día.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f9873222-3c05-49c4-8a74-a3eb12367c8f', 'Percentage Rent', '4', '2.III', 'RENTA VARIABLE', E'- An 8% rate is applied to net sales to calculate a new amount.\n- From this amount, the fixed rent is subtracted.\n- The difference is subject to Value Added Tax (IVA) to determine the new variable rent amount.\n- Net sales include all income from the property and tenant''s sales, minus IVA, bonuses, tips, returns, discounts, and credit card commissions.\n- The tenant must provide a truthful income report by the 10th of each month for the previous month, detailing total income, deductions, and net sales.\n- Reports should be uploaded to the landlord''s system or sent signed by an authorized representative if the system fails.\n- The landlord can appoint an inspector to verify monthly net sales, and the tenant must provide access to all necessary information and documentation.', E'Al monto que resulte por ventas netas se le aplicará el porcentaje 8%, y la cantidad que resulte de esta operación, se le descontará el monto de RENTA FIJA, la diferencia de lo anterior, se le aplicará el Impuesto al Valor Agregado (IVA), y este resultado será el nuevo monto a pagar como RENTA VARIABLE.\n\nSe consideran ventas netas para efectos del CONTRATO, todos los ingresos que se obtengan en "EL BIEN" por cualquier concepto, y los obtenidos por el ARRENDATARIO por ventas de mercancías, bienes o servicios del Establecimiento Mercantil instalado en "EL BIEN", deducidos con el Impuesto al Valor Agregado (IVA), las bonificaciones, propinas, devoluciones y descuentos efectivamente realizadas, así como las comisiones por tarjetas de crédito por recibir los ingresos a través de ellas, sin importar que se entreguen comprobantes, recibos u otro documento que amparen la venta o prestación del servicio en un lugar distinto a "EL BIEN".\n\nPara efectos de que la ARRENDADORA pueda verificar el cálculo antes señalado, el ARRENDATARIO conviene y se obliga a entregar dentro de los primeros 10 (Diez) días naturales de cada mes, respecto del mes inmediato anterior, un informe por escrito en el que asiente con toda veracidad y bajo protesta de decir verdad, los ingresos totales, las deducciones y las ventas netas obtenidas de acuerdo a lo establecido en la presente Cláusula (Reporte de Ingresos), los cuales deberán subirse al sistema que señale la ARRENDADORA, en caso de que el sistema falle deberán ser enviados debidamente firmados por su apoderado y/o por su contador público, donde consten los elementos utilizados para el cálculo de la RENTA VARIABLE y para la determinación del diferencial resultante. Además de lo anterior, la ARRENDADORA tendrá la facultad de que un interventor, a su costa, verifique las ventas netas mensuales del ARRENDATARIO, obligándose este último a proporcionar todos los informes, dar acceso a la información y documentación de su contabilidad, y otorgar las facilidades necesarias para llevar a cabo dicha verificación.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f9873222-3c05-49c4-8a74-a3eb12367c8f', 'Incremento de Renta', '4', '2.IV', 'INCREMENTO EN RENTA', E'- The fixed rent will first increase in the 25th month from the "Delivery Date" specified in the contract.\n- After the first increase, the fixed rent will go up annually, every 12 months.\n- The increase will be based on the National Consumer Price Index (INPC) from the previous 12 months, capped at 7%.\n- This adjusted amount will be the new fixed rent for the next year.\n- At the start of each contract renewal, the rent may be adjusted using the INPC plus an additional 3 percentage points, if deemed necessary.', 'Las PARTES convienen que, el monto de la RENTA FIJA vigente será incrementado por primera vez al mes 25 (veinticinco,) contados en la fecha enmarcada dentro de la carátula como "FECHA DE ENTREGA DEL BIEN". A partir de dicho primer ajuste, la RENTA FIJA se incrementará de forma anual, es decir cada 12 (doce) meses. Para el incremento de la RENTA FIJA vigente se aplicará, el Índice Nacional de Precios al Consumidor (INPC) que resulte de los últimos 12 (Doce) meses del año inmediato anterior a la fecha en que corresponda el incremento topado hasta el 7%, y ese resultado será la nueva RENTA FIJA a pagar por el periodo anual siguiente. Las PARTES acuerdan que, al inicio de cada prórroga del presente Contrato, conforme al INPC más 3 tres puntos porcentuales, con el fin de ajustarlo si así lo consideran necesario.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('f9873222-3c05-49c4-8a74-a3eb12367c8f', 'Common Area Maintenance Charges', '8', '14', 'MANTENIMIENTO Y OPERACIÓN DEL CENTRO COMERCIAL', E'- The tenant is responsible for maintaining, conserving, and cleaning the property to keep it in excellent condition, following the schedule in the Shopping Center''s Operation Regulations.\n- The tenant must pay a monthly maintenance fee equal to 10% of the current fixed rent, plus VAT, for the upkeep of common areas in the shopping center.\n- This fee covers maintenance, cleaning, security, insurance, utilities, and equipment maintenance (like air conditioning and elevators), as well as any future installations.\n- It also includes costs for roads, parking, access points, rooftops, ramps, and administrative expenses, along with any advertising services that benefit the tenant in relation to the shopping center.', E'EI ARRENDATARIO asume la obligación de realizar por su cuenta y cargo, el pago del mantenimiento, conservación y limpieza de "EL BIEN" de tal forma que siempre se encuentre en óptimas condiciones, asimismo, se obliga a respetar en todo momento los horarios establecidos para ello en el Reglamento de Operación del Centro Comercial.\n\n14.II.- EI ARRENDATARIO conviene y se obliga a pagar mensualmente, una cantidad equivalente al 10% (diez por ciento) sobre el importe de la RENTA FIJA vigente, más el Impuesto al Valor Agregado (IVA), por concepto de Cuota de Mantenimiento para las áreas comunes del CENTRO COMERCIAL, los cuales corresponderán de manera enunciativa más no limitativa, a mantenimiento, limpieza, seguridad, vigilancia, seguros contra daños y responsabilidad civil, energía eléctrica, agua, mantenimiento de equipos de aire acondicionado, elevadores, cualquier otro equipo electromecánico y cualquier otro equipo que exista o que llegare a instalarse en un futuro, incluyendo las vialidades, estacionamientos, accesos, azoteas y rampas y demás gastos de administración y mantenimiento, así como los servicios publicitarios de cualquier tipo en beneficio del ARRENDATARIO en relación con el CENTRO COMERCIAL.');
